      prompt: "A utility must choose between upsizing a trunk and an aggressive I and I program to meet a 20 year capacity need.",
      topicId: "capacity-planning",
      level: "class1",
      assumptions: "Fictional Ontario utility capacity options analysis with given values. Observations are as stated.",
      evidence: [
        {
          id: "ev1",
          label: "Measured removable infiltration in the trunk catchment equals 70 percent of the projected 20 year capacity shortfall."
        },
        {
          id: "ev2",
          label: "A completed pilot removed infiltration at a cost per unit of capacity well below the trunk upsizing unit cost."
        },
        {
          id: "ev3",
          label: "Even with all removable infiltration removed, growth still requires a smaller trunk relief project in year 15."
        },
        {
          id: "ev4",
          label: "Upsizing alone leaves infiltration flows in the system, and wet weather peaks continue to grow with groundwater."
        }
      ],
      inference: {
        id: "inference",
        prompt: "Which explanation is best supported by all of the observations?",
        options: [
          {
            id: "inf-a",
            label: "Upsizing alone is the complete answer"
          },
          {
            id: "inf-b",
            label: "I and I removal plus a smaller deferred relief project is the supported plan, because removal covers most of the shortfall at lower unit cost"
          },
          {
            id: "inf-c",
            label: "Neither option is needed because capacity shortfalls resolve themselves"
          },
          {
            id: "inf-d",
            label: "I and I removal alone covers the entire 20 year need with no relief project"
          }
        ],
        correctOptionId: "inf-b",
        explanation: "Removal covers 70 percent at lower unit cost but not all of it, so removal plus deferred smaller relief matches both limits. Upsizing alone ignores the cheaper capacity and the growing infiltration."
      },
      nextClue: {
        id: "next-clue",
        prompt: "Which next step best confirms the explanation?",
        options: [
          {
            id: "nc-a",
            label: "Programming I and I removal first with trunk relief deferred and downsized, tracked against measured removal each phase"
          },
          {
            id: "nc-b",
            label: "Building the full trunk upsizing in year one"
          },
          {
            id: "nc-c",
            label: "Cancelling both options and monitoring"
          }
        ],
        correctOptionId: "nc-a",
        explanation: "Sequencing removal first and deferring the smaller relief follows the measured shares and unit costs."
      },
      clueText: {
        "nc-a": "Phase removal tracking shows capacity being recovered at the pilot unit cost.",
        "nc-b": "Year one full upsizing spends on capacity that removal provides more cheaply.",
        "nc-c": "The shortfall is projected from measured flows, so monitoring alone does not create capacity."
      }
